<?php
ini_set('display_errors','0'); error_reporting(E_ALL); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store');
$R=__DIR__.'/..'; require "$R/lib/Db.php"; require "$R/lib/Jwt.php"; require "$R/lib/LineImageCompressor.php"; $CFG=require "$R/config.php";
function ls2_json($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;} function ls2_err($m,$s=400){ls2_json(['error'=>$m],$s);} function ls2_user(){global $CFG;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))ls2_err('توکن نامعتبر است',401);$p=Jwt::verify(trim($m[1]),$CFG['jwt_secret']);if(!$p)ls2_err('توکن منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.role_id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])ls2_err('کاربر نامعتبر است',401);return $u;} function ls2_admin($u){return !empty($u['is_admin'])||in_array($u['role_title']??'', ['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true);} function ls2_ids($u){if(ls2_admin($u))return null;try{$r=Db::all('SELECT line_id FROM user_lines WHERE user_id=?',[$u['id']]);return array_map('intval',array_column($r,'line_id'));}catch(Throwable $e){return null;}}
function ls2_schema(){Db::run("CREATE TABLE IF NOT EXISTS station_sign_types(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,code VARCHAR(80) NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_sst_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");foreach(["station_code VARCHAR(80) NULL","station_status VARCHAR(30) NOT NULL DEFAULT 'registered'"] as $d){$c=strtok($d,' ');$n=Db::one("SELECT COUNT(*) c FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='line_station_locations' AND COLUMN_NAME=?",[$c]);if(!(int)($n['c']??0))Db::run("ALTER TABLE line_station_locations ADD COLUMN `$c` ".substr($d,strlen($c)));}Db::run("CREATE TABLE IF NOT EXISTS line_station_signs(id BIGINT AUTO_INCREMENT PRIMARY KEY,station_location_id BIGINT NOT NULL,sign_type_id INT NOT NULL,photo_path VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_station(station_location_id),INDEX idx_type(sign_type_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");foreach(["station_location_id BIGINT NULL","station_code VARCHAR(80) NULL","purpose VARCHAR(40) NOT NULL DEFAULT 'station_attendance'","base_radius_m INT NOT NULL DEFAULT 100","edge_tolerance_m INT NOT NULL DEFAULT 0"] as $d){$c=strtok($d,' ');$n=Db::one("SELECT COUNT(*) c FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='geofences' AND COLUMN_NAME=?",[$c]);if(!(int)($n['c']??0))Db::run("ALTER TABLE geofences ADD COLUMN `$c` ".substr($d,strlen($c)));}foreach([['تابلو ایستگاه تاکسی ساده','simple',1],['تابلو ایستگاه تاکسی دارای بارکرد','barcard',2],['تابلو ایستگاه تاکسی حمل با جرثقیل','crane',3],['تابلو ایستگاه دارای دوربین نظارتی پلیس','police_camera',4]] as $d)Db::run('INSERT IGNORE INTO station_sign_types(title,code,is_active,sort_order) VALUES(?,?,1,?)',[$d[0],$d[1],$d[2]]);}
function ls2_store($v,$pre){if(!is_string($v)||$v==='')return null;if(strpos($v,'base64,')!==false){$v=substr($v,strpos($v,',')+1);$v=base64_decode($v,true);}if(!is_string($v)||strlen($v)>8*1024*1024||@getimagesizefromstring($v)===false)ls2_err('تصویر نامعتبر یا بزرگ‌تر از ۸ مگابایت است');$rel='/uploads/line-locations/'.date('Y/m').'/';$dir=__DIR__.$rel;@mkdir($dir,0775,true);$p=$dir.$pre.'_'.bin2hex(random_bytes(8)).'.jpg';if(!LineImageCompressor::fromBinary($v,$p))ls2_err('فشرده‌سازی تصویر در دسترس نیست',500);return $rel.basename($p);}
function ls2_edge_tolerance(){try{$r=Db::one("SELECT value FROM app_settings WHERE `key`='checkin_error_radius_m'");$v=$r?(int)$r['value']:0;return max(0,$v);}catch(Throwable $e){return 0;}}
function ls2_sync_geofence($lineId,$stationId,$code,$name,$lat,$lng){$lineId=(int)$lineId;$stationId=(int)$stationId;$code=trim((string)$code);$name=trim((string)$name);$old=[];if($code!=='')$old=Db::all("SELECT id FROM geofences WHERE line_id=? AND id<>? AND ((station_location_id IS NOT NULL AND station_location_id IN (SELECT id FROM line_station_locations WHERE line_id=? AND station_code=?)) OR station_code=?)",[$lineId,$stationId,$lineId,$code,$code]);if(!$old&&$name!=='')$old=Db::all("SELECT id FROM geofences WHERE line_id=? AND station_location_id IS NULL AND name=?",[$lineId,$name]);if($old){$ids=array_values(array_unique(array_map('intval',array_column($old,'id'))));if($ids){$in=implode(',',array_fill(0,count($ids),'?'));Db::run("DELETE FROM geofences WHERE id IN ($in)",$ids);}}$edge=ls2_edge_tolerance();Db::run("INSERT INTO geofences(name,line_id,type,center_lat,center_lng,radius_m,polygon,station_location_id,station_code,purpose,base_radius_m,edge_tolerance_m) VALUES(?,?,'circle',?,?,100,NULL,?,?,?,100,?)",[$name!==''?$name:($code!==''?'ایستگاه '.$code:'ایستگاه'),$lineId,(float)$lat,(float)$lng,$stationId,$code!==''?$code:null,'station_attendance',$edge]);return (int)Db::lastId();}
$u=ls2_user();ls2_schema();$op=$_GET['op']??$_POST['op']??'permission';
if($op==='permission')ls2_json(['allowed'=>true,'can_manage'=>ls2_admin($u),'station_geofence_base_radius_m'=>100,'station_geofence_edge_tolerance_m'=>ls2_edge_tolerance()]);
if($op==='lines'){$is=ls2_ids($u);$w='';$a=[];if(is_array($is)){if(!$is)ls2_json([]);$w=' WHERE l.id IN('.implode(',',array_fill(0,count($is),'?')).')';$a=$is;}ls2_json(Db::all("SELECT l.id,l.code,l.origin,l.destination FROM `lines` l$w ORDER BY l.code",$a));}
if($op==='sign-types')ls2_json(Db::all('SELECT id,title,code FROM station_sign_types WHERE is_active=1 ORDER BY sort_order,title'));
if($op==='save-sign-type'){if(!ls2_admin($u))ls2_err('دسترسی مدیریت نوع تابلو ندارید',403);$b=json_decode(file_get_contents('php://input'),true)?:$_POST;$id=(int)($b['id']??0);$t=trim((string)($b['title']??''));$c=trim((string)($b['code']??''));if(!$t)ls2_err('عنوان نوع تابلو الزامی است');if($id)Db::run('UPDATE station_sign_types SET title=?,code=?,is_active=? WHERE id=?',[$t,$c?:null,!empty($b['is_active'])?1:0,$id]);else Db::run('INSERT INTO station_sign_types(title,code,is_active,sort_order) VALUES(?,?,?,999)',[$t,$c?:null,!empty($b['is_active'])?1:0]);ls2_json(['ok'=>true]);}
if($op==='delete-sign-type'){if(!ls2_admin($u))ls2_err('دسترسی مدیریت نوع تابلو ندارید',403);Db::run('UPDATE station_sign_types SET is_active=0 WHERE id=?',[(int)($_GET['id']??$_POST['id']??0)]);ls2_json(['ok'=>true]);}
if($op==='nearest'){ $lat=(float)($_GET['lat']??0);$lng=(float)($_GET['lng']??0);$rad=min(2000,max(50,(float)($_GET['radius']??500)));if($lat<-90||$lat>90||$lng<-180||$lng>180)ls2_err('مختصات نامعتبر است');$is=ls2_ids($u);$w='';$a=[];if(is_array($is)){if(!$is)ls2_json(['stations'=>[]]);$w=' AND s.line_id IN('.implode(',',array_fill(0,count($is),'?')).')';$a=$is;}$rows=Db::all("SELECT s.id,s.line_id,s.station_code,s.station_name,s.station_status,s.latitude,s.longitude,l.code line_code,l.origin,l.destination FROM line_station_locations s JOIN `lines` l ON l.id=s.line_id WHERE s.latitude IS NOT NULL AND s.longitude IS NOT NULL$w ORDER BY s.captured_at DESC",$a);$seen=[];$out=[];foreach($rows as $r){$key=($r['station_code']?:'id'.$r['id']).'|'.$r['line_id'];if(isset($seen[$key]))continue;$seen[$key]=1;$d=6371000*2*asin(sqrt(pow(sin(deg2rad(((float)$r['latitude']-$lat)/2)),2)+cos(deg2rad($lat))*cos(deg2rad((float)$r['latitude']))*pow(sin(deg2rad(((float)$r['longitude']-$lng)/2)),2)));if($d<=$rad){$r['distance_m']=round($d,1);$out[]=$r;}}usort($out,function($x,$y){return $x['distance_m']==$y['distance_m']?0:($x['distance_m']<$y['distance_m']?-1:1);});ls2_json(['stations'=>array_slice($out,0,20),'radius_m'=>$rad]);}
if($op==='search'){ $q=trim((string)($_GET['q']??''));if($q==='')ls2_json([]);$is=ls2_ids($u);$w='';$a=[];if(is_array($is)){if(!$is)ls2_json([]);$w=' AND s.line_id IN('.implode(',',array_fill(0,count($is),'?')).')';$a=$is;}$l='%'.$q.'%';ls2_json(Db::all("SELECT s.id,s.line_id,s.station_code,s.station_name,s.station_status,s.latitude,s.longitude,l.code line_code FROM line_station_locations s JOIN `lines` l ON l.id=s.line_id WHERE (s.station_code LIKE ? OR s.station_name LIKE ? OR l.code LIKE ?)$w ORDER BY s.station_code LIMIT 50",array_merge([$l,$l,$l],$a)));}
if($op==='history'){ $id=(int)($_GET['station_id']??0);ls2_json(Db::all("SELECT s.*, (SELECT COUNT(*) FROM line_station_signs z WHERE z.station_location_id=s.id) sign_count FROM line_station_locations s WHERE s.id=? OR (s.station_code IS NOT NULL AND s.station_code=(SELECT station_code FROM line_station_locations WHERE id=?)) ORDER BY s.captured_at DESC LIMIT 100",[$id,$id]));}
if($op==='capture'){ $b=json_decode(file_get_contents('php://input'),true)?:$_POST;$lid=(int)($b['line_id']??0);$line=Db::one('SELECT id,code FROM `lines` WHERE id=?',[$lid]);if(!$line)ls2_err('خط انتخاب‌شده وجود ندارد',404);$is=ls2_ids($u);if(is_array($is)&&!in_array($lid,$is,true))ls2_err('این خط در محدوده دسترسی شما نیست',403);$lat=$b['latitude']??null;$lng=$b['longitude']??null;$acc=$b['accuracy_m']??null;if(!is_numeric($lat)||!is_numeric($lng)||!is_numeric($acc)||$lat<-90||$lat>90||$lng<-180||$lng>180||$acc<0)ls2_err('مختصات یا دقت GPS نامعتبر است');if((float)$acc>20)ls2_err('دقت GPS باید حداکثر ۲۰ متر باشد',422);$status=($b['station_status']??'registered')==='missing'?'missing':'registered';$code=trim((string)($b['station_code']??''));$name=trim((string)($b['station_name']??''));if($status==='registered'&&!$code)ls2_err('شماره ایستگاه الزامی است');$ss=$b['signs']??[];if(!is_array($ss)||!count($ss))ls2_err('حداقل یک تابلو الزامی است');$now=date('Y-m-d H:i:s');Db::run('INSERT INTO line_station_locations(line_id,station_code,station_status,station_name,latitude,longitude,accuracy_m,captured_by,captured_at) VALUES(?,?,?,?,?,?,?,?,?)',[$lid,$code?:null,$status,$name?:null,$lat,$lng,$acc,$u['id'],$now]);$sid=(int)Db::lastId();foreach($ss as $x){$tid=(int)($x['type_id']??0);if(!Db::one('SELECT id FROM station_sign_types WHERE id=? AND is_active=1',[$tid]))ls2_err('نوع تابلو نامعتبر است');$p=ls2_store($x['photo']??null,'station-sign');if(!$p)ls2_err('تصویر تابلو الزامی است');Db::run('INSERT INTO line_station_signs(station_location_id,sign_type_id,photo_path) VALUES(?,?,?)',[$sid,$tid,$p]);}$geo=ls2_sync_geofence($lid,$sid,$code,$name,$lat,$lng);Db::run('UPDATE `lines` SET latitude=?,longitude=?,location_accuracy_m=?,station_name=?,location_updated_by=?,location_updated_at=? WHERE id=?',[$lat,$lng,$acc,$name?:null,$u['id'],$now,$lid]);$ge=Db::one('SELECT base_radius_m,edge_tolerance_m FROM geofences WHERE id=?',[$geo])?:['base_radius_m'=>100,'edge_tolerance_m'=>0];ls2_json(['ok'=>true,'id'=>$sid,'geofence_id'=>$geo,'geofence_base_radius_m'=>(int)$ge['base_radius_m'],'geofence_edge_tolerance_m'=>(int)$ge['edge_tolerance_m'],'effective_max_distance_m'=>(int)$ge['base_radius_m']+(int)$ge['edge_tolerance_m'],'line_code'=>$line['code'],'station_code'=>$code?:null,'station_status'=>$status,'updated_at'=>$now]);}
if($op==='sign-report'){if(!ls2_admin($u))ls2_err('دسترسی گزارش تابلوها ندارید',403);$t=(int)($_GET['type_id']??0);ls2_json(Db::all("SELECT s.id,s.station_code,s.station_status,s.station_name,s.latitude,s.longitude,s.accuracy_m,s.captured_at,l.code line_code,l.origin,l.destination,t.title sign_type,sg.photo_path,CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,'')) captured_by FROM line_station_signs sg JOIN line_station_locations s ON s.id=sg.station_location_id JOIN station_sign_types t ON t.id=sg.sign_type_id JOIN `lines` l ON l.id=s.line_id LEFT JOIN users u ON u.id=s.captured_by WHERE (?=0 OR t.id=?) ORDER BY s.captured_at DESC",[$t,$t]));}
ls2_err('عملیات نامعتبر است',404);
